for(const paragraph of raw.split('\n')){
  let line='';
  // Keep words intact where possible; CJK breaks between characters.
  const chunks=paragraph.match(/[\x21-\x2c\x2e-\x7e]+-?|-| +|[^\x21-\x7e ]/gu)||[''];
  for(const chunk of chunks){
    if(line&&measure(line+chunk)>available){lines.push(line.trimEnd());line='';}
    for(const ch of Array.from(chunk)){if(line&&measure(line+ch)>available){lines.push(line.trimEnd());line='';}if(line||ch!==' ')line+=ch;}
  }
  lines.push(line.trimEnd());
}
const maxRows=component==='Text'||component==='Link'?1:Math.max(1,Math.floor(Number(i.rows)||1));
const tail=String(i.suffix||'');
const collapsed=!!i.ellipsis&&!i.expanded&&!editing;
let truncated=collapsed&&(lines.length>maxRows||measure(lines[lines.length-1]||'')+actionWidth>available);
let expandLabel=truncated&&i.expandable?(i.symbol||'Expand'):i.expanded&&i.expandable?'Collapse':'';
const labelWidth=expandLabel?measure(expandLabel)+4:0;
if(collapsed){
 lines=lines.slice(0,maxRows);
 if(truncated){let last=Array.from(lines.pop()||'');while(last.length&&measure(last.join('')+'…'+tail)+actionWidth+labelWidth>available)last.pop();lines.push(last.join('').trimEnd()+'…'+tail);}
}
if((!collapsed||!truncated)&&tail)lines[lines.length-1]+=tail;
// Inline actions follow the last line, wrapping together when no room remains.
if(!start&&!truncated&&measure(lines[lines.length-1])+actionWidth+labelWidth>available)lines.push('');
function rect(name,x,y,w,h,fill,stroke,radius=0){nodes.push({type:'rectangle',name,x,y,width:Math.max(0,w),height:Math.max(0,h),fill,cornerRadius:radius,...(stroke?{stroke,strokeWidth:1,strokeAlignment:'inner'}:{})});}
function text(content,x,y,size=textSize,fill=color,name='Text'){nodes.push({type:'text',name,content,x,y,fontFamily:font,fontSize:size,fontWeight:String(weight),fontStyle:italic?'italic':'normal',lineHeight:lh/size,textGrowth:'auto',fill,underline:!!i.underline,strikethrough:!!i.delete});}
function icon(name,x,y,size,fill){for(const path of icons[name].paths)nodes.push({type:'path',name,x,y,width:size,height:size,viewBox:icons[name].viewBox,geometry:path,fill});}
rect('Typography surface',0,0,W,H,t.colorBgContainer);
if(i.editable&&i.editing){
 const height=Math.max(lh+10,Number(pencil.height)||lh+10);
 rect('Editing surface',0,0,W,height,t.colorBgContainer,t.colorPrimary,6);
 // Textarea interior: 11px inline padding, 4px block padding; confirmation at bottom right.
 for(let row=0;row<lines.length;row++)text(lines[row],12,4+row*lh);
 if(i.enterIcon!=='none')icon(i.enterIcon||'EnterOutlined',W-24,height-22,14,t.colorTextDescription);
 return nodes;
}
for(let row=0;row<lines.length;row++){
 const s=lines[row],y=row*lh,x=start&&row===0?actionWidth:0;
 const tw=measure(s);
 for(const box of decoration.boxes){
   const mark=box.kind==='mark',kbd=box.kind==='kbd';
   rect(mark?'Mark background':kbd?'Keyboard background':'Code background',x+box.x,y+box.y,tw+box.extra,box.height,mark?'#FFE58F':kbd?'#9696960F':'#9696961A',mark?null:'#64646433',mark?0:3);
   if(kbd)rect('Keyboard bottom border',x+box.x+1,y+box.y+box.height-2,tw+box.extra-2,1,'#64646433');
 }
 text(s,x+edge,y,textSize,i.mark&&!i.disabled?'#000000':color);
}
let ax=start?0:measure(lines[lines.length-1])+edge*2;
const ay=start?0:(lines.length-1)*lh;
if(expandLabel){text(expandLabel,ax+4,ay,textSize,operation,'Ellipsis action');ax+=labelWidth;}
// Ant icons inherit font size and align -0.125em from the text baseline.
const baselineOffset=boxes[[fs,weight,italic?1:0,0].join(':')].baseline;
for(const name of actions){
 const x=ax+(!raw?0:4);
 icon(name,x,ay+baselineOffset-fs*.875,fs,i.copied&&name===(i.copiedIcon||'CheckOutlined')?t.colorSuccessText:operation);
 ax+=fs+4;
}
return nodes;
